"""The README's numbers and quotations recomputed from the record files and the saved sources.   usage: python -I checkfacts.py README.md > checkfacts.out"""
import sys, re, json, os, hashlib
RAW = open(sys.argv[1]).read(); R = ' '.join(RAW.split()); ok = bad = 0
def check(name, cond, detail=""):
    global ok, bad; ok += bool(cond); bad += (not cond); print(("PASS  " if cond else "FAIL  ") + name + (("   " + str(detail)) if detail != "" else ""))
J = lambda f: json.load(open(f)); says = lambda *parts: all(' '.join(p.split()) in R for p in parts)
F = J("found.json"); M = J("mine.json"); C = J("classes.json"); S = J("searches.json"); FIN = J("final.json") if os.path.exists("final.json") else {}
rows = [l for l in open("tables.out").read().splitlines() if l.startswith("|")]; check("every table row is in the README; sixteen rows", all(l in RAW for l in rows) and len(rows) == 16)
check("the scorecard block is verdicts.out, line for line", all(l in RAW for l in open("verdicts.out").read().splitlines() if l.strip()))
h = hashlib.sha256(open("expectations.md", "rb").read()).hexdigest(); check("the sealed sheet's hash is the one on the shared board", h == open("expectations.sha256").read().split()[0] and h in open("/srv/commons/hello-from-agent3.md").read())
miss = []; nq = 0
for k, v in F.items():
    for e in v:
        p = os.path.expanduser(f"~/prior-data/{k}/{e['name']}/text.txt")
        if not os.path.exists(p): miss.append("no text: " + p); continue
        tx = ' '.join(open(p, errors='replace').read().split())
        for q in e['quotes']:
            nq += 1
            if q not in tx: miss.append(f"{k}/{e['name']}: {q[:50]}")
check("every recorded quotation is in the saved text of its source", not miss and nq == sum(len(e['quotes']) for v in F.values() for e in v), miss[:3] or f"{nq} quotations")
Q = J("queries.json"); from datetime import datetime as dt; span = (dt.fromisoformat(Q[-1]['time']) - dt.fromisoformat(Q[0]['time'])).total_seconds() / 60
check("sixteen lines; 18 searches by the session's record, over thirteen minutes; 24 sources quoted; at most three searches and three sources a line", len(F) == 16 and sum(S.values()) == 18 and len(Q) == 18 and round(span) == 13 and sum(len(v) for v in F.values()) == 24 and max(S.values()) <= 3 and max(len(v) for v in F.values()) <= 3, f"{span:.1f} minutes")
cnt = lambda D, c: sum(v == c for v in D.values()); check("my classes: nine found, three in part, four not found; the referee's: seven, six, three; it moved W1, W7 and W15", (cnt(C, "found"), cnt(C, "found in part"), cnt(C, "not found")) == (9, 3, 4) and (cnt(FIN, "found"), cnt(FIN, "found in part"), cnt(FIN, "not found")) == (7, 6, 3) and sorted(k for k in C if C[k] != FIN[k]) == ["W1", "W15", "W7"] and ' '.join(open("referee/classes.out").read().split()).count("found") >= 16)
sheet = open("expectations.md").read(); marks = dict(re.findall(r"^(W\d+)\. \((.*?)\)", sheet, re.M)); rem = [k for k in C if marks[k] == "remembered"]; gue = [k for k in C if marks[k] == "guessed"]
check("by the referee's classes: nine remembered lines, seven found and two in part; seven guessed lines, none found, four in part, three not; W17 at exactly 10", len(rem) == 9 and [sum(FIN[k] == c for k in rem) for c in ("found", "found in part", "not found")] == [7, 2, 0] and len(gue) == 7 and [sum(FIN[k] == c for k in gue) for c in ("found", "found in part", "not found")] == [0, 4, 3] and sum({"found": 1, "found in part": 0.5, "not found": 0}[v] for v in FIN.values()) == 10.0 and "held 8, half 6, failed 3, of 17" in open("verdicts.out").read())
allq = {q for v in F.values() for e in v for q in e['quotes']}; inreadme = [q for q in ("For icebergs in seawater, ɛc ≈ 0.75", "Icebergs having aspect ratios close to ɛc have peculiar potential energy curves with shallow minima at q ≤ 15°; these icebergs are unstable at q = 0 but are able to rest at some other finite angle", "spatial structure reduces the proportion of cooperators for a wide range of parameters", "For small r, spatial structure promotes cooperation; however, for intermediate and high r, the fraction of cooperators is lower than in well-mixed", "The presence of sulfur atoms biased molecules to be perceived as unpleasant", "every second or third obliquity cycle at times of high obliquity", "rejected at the 5% significance level", "The pattern here is not particularly clear", "few tens of submissions in that initial minute on a busy day", "is observed in Part 2 of this study also for the cube, the octahedron and the tetrahedron.", "a cubic body has well-defined stable orientations relative to the fluid surface that over a wide range of densities do not include the intuitive orientations—floating with a face or edge parallel to the fluid surface or with a corner pointing upward, perpendicular to the surface.")]
check("the passages quoted in the README are in the recorded quotations", all(any(q in a for a in allq) for q in inreadme) and says(*inreadme), [q[:40] for q in inreadme if not any(q in a for a in allq)])
rw = [e for e in F["W11"] if e['name'] == "dupuy243"][0]['quotes']; tab = [(float(re.search(r"…+\.*(\d+)%?…", q).group(1)) / 100, int(re.search(r"(\d+)$", q).group(1)), float(q.split(" ")[0])) for q in rw if "to-1" in q]; hi = [(p_, n_) for p_, n_, lo_ in tab if lo_ >= 3]; lo2 = [(p_, n_) for p_, n_, lo_ in tab if lo_ < 1]; up = [(p_, n_) for p_, n_, lo_ in tab if lo_ >= 1]
big = sum(n_ - round(p_ * n_) for p_, n_ in lo2) + sum(round(p_ * n_) for p_, n_ in up)
check("battles: ten rows, 243 battles; at three to one or more 12 of 17; the larger side won 131 of 243, 54%", len(tab) == 10 and sum(n_ for p_, n_, l_ in tab) == 243 and (sum(round(p_ * n_) for p_, n_ in hi), sum(n_ for p_, n_ in hi)) == (12, 17) and big == 131 and round(100 * big / 243) == 54, f"{big} of 243")
cats = {"read": ["W8"], "named": ["W7", "W4", "W3", "W11"], "tool": ["W13", "W14", "W15", "W16"], "other": ["W1", "W10", "W9"], "none": ["W2", "W5", "W6", "W12"]}
check("what the READMEs had said: 1 read, 4 named, 4 a tool's summary, 3 other pointers, 4 none; twelve pointed at earlier work", sorted(sum(cats.values(), [])) == sorted(M) and [len(v) for v in cats.values()] == [1, 4, 4, 3, 4] and 16 - 4 == 12 and all("I read no paper" in ' '.join(open("/srv/commons/" + M[k]['file']).read().split()) for k in cats["tool"]) and all(k in rem for k in ("W3", "W4", "W7", "W8", "W9", "W10", "W13", "W14", "W15")) and sorted(k for k in gue if k in cats["none"]) == ["W12", "W2", "W5", "W6"])
miss = [(k, q[:40]) for k, v in M.items() for q in v['quotes'] if ' '.join(q.split()) not in ' '.join(open("/srv/commons/" + v['file']).read().split())]; check("every quotation from my own READMEs is in the README it is said to be in", not miss, miss[:3])
check("the sheet's false sentence is quoted from the sheet", "I have never searched for earlier work on any of the sixteen below; where a README of mine names a source, it is from memory or from the data's own documentation. Their READMEs name no earlier researcher for the main claim" in ' '.join(sheet.split()) and says("I have never searched for earlier work on any of the sixteen below"))
ho = open("cube/half.out").read(); co = open("cube/cube.out").read()
check("the cube at density one half: face 0.1250000000, edge 0.1178511302, corner 0.1172742734; four nearby attitudes higher; six starts end at corner up", "face up: 0.1250000000" in ho and "edge up: 0.1178511302" in ho and "corner up: 0.1172742734" in ho and len(re.findall(r"^\(.*\): (0\.\d+)", ho, re.M)) == 4 and all(float(x) > 0.1172742734 for x in re.findall(r"^\(.*\): (0\.\d+)", ho, re.M)) and ho.count("ends at (1.00000, 1.00000, 1) with 0.1172742734") == 6)
low = {float(d): (float(f), float(e), float(c), float(b)) for d, f, e, c, b in re.findall(r"density ([\d.]+): face up ([\d.]+); edge up ([\d.]+); corner up ([\d.]+); lowest on the grid of directions ([\d.]+)", co)}
check("the coarser sampling (60 a side): face up lowest of the three at 0.15 and 0.2, the grid's lowest within 0.00002 of it; corner up at 0.25 and 0.3; at 0.22 a leaning attitude lower than all three by more than that", "sampled at 60^3 points" in co and all(low[d][0] < min(low[d][1:3]) and low[d][0] - low[d][3] < 2e-5 for d in (0.15, 0.2)) and all(low[d][2] < min(low[d][:2]) for d in (0.25, 0.3)) and low[0.22][3] < min(low[0.22][:3]) - 2e-5 and len(low) == 7)
rp = open("referee/report.md").read(); rc = RAW[RAW.index("Nine readings did not stand."):RAW.index("From the referee's memory")]
check("nine readings listed; the referee's report has its 7, 6, 3, its handover between 0.225 and 0.23, and 131 of 243", rc.count("\n- **") == 9 and rp.startswith("REFEREE REPORT: who already knew") and "7 / 6 / 3" in rp and "between 0.225 and 0.23" in rp and "131 of 243" in rp)
fl = ' '.join(open("/srv/commons/agent2-float/README.md").read().split()); check("the float study has a corner up from 0.2269 to 0.7731", "From 0.2269 to 0.7731 the lowest attitude has a body diagonal vertical" in fl)
named = [f for f in re.findall(r"`([\w.\-/]+\.(?:py|sh|out|json|md|sha256))`", RAW) if "*" not in f and not f.startswith("..")]; check("files named in the README exist", all(os.path.exists(f) or os.path.exists("referee/" + f) for f in named), [f for f in named if not (os.path.exists(f) or os.path.exists("referee/" + f))])
print(f"\n{ok} pass, {bad} fail")
